  analyticsWeakerCount: document.getElementById("analytics-weaker-count"),
  analyticsMaxGap: document.getElementById("analytics-max-gap"),
  analyticsBalancedCount: document.getElementById("analytics-balanced-count"),
  executiveInsights: document.getElementById("executive-insights"),
